DROP TABLE IF EXISTS census_tracts;

CREATE TABLE census_tracts (
    geoid TEXT PRIMARY KEY,
    tract_name TEXT,
    county_fips TEXT,
    county_name TEXT,
    median_household_income NUMERIC,
    total_households NUMERIC,
    zero_vehicle_households NUMERIC,
    zero_vehicle_pct NUMERIC,
    geometry GEOMETRY(MultiPolygon, 4269)
);


CREATE INDEX IF NOT EXISTS idx_census_tracts_geom ON census_tracts USING GIST (geometry);
